require_once 'includes/auth.php'; require_once 'config/koneksi.php';
function countRows($conn,$sql){$r=$conn->query($sql)->fetch_assoc();return $r['total']??0;}
$total_siswa=countRows($conn,"SELECT COUNT(*) total FROM siswa WHERE status='aktif'");$total_trx=countRows($conn,"SELECT COUNT(*) total FROM pembayaran");$total_nominal=countRows($conn,"SELECT COALESCE(SUM(jumlah),0) total FROM pembayaran");
$recent=$conn->query("SELECT p.no_transaksi,p.tanggal_bayar,p.jumlah,p.metode_pembayaran,s.nama_siswa,j.nama_jenis FROM pembayaran p JOIN siswa s ON s.id_siswa=p.id_siswa JOIN jenis_pembayaran j ON j.id_jenis=p.id_jenis ORDER BY p.id_pembayaran DESC LIMIT 6");
$page_title='Dashboard';$active='dashboard';include 'includes/header.php';?>
